دالة هل_متوازنة(نص) {
    متغير ق = [ ]
    من_أجل (ح في نص) {
        إذا (ح == '(' أو ح == '[' أو ح == '{') {
            أضف(ق, ح)
        } وإلا إذا (ح == ')' أو ح == ']' أو ح == '}') {
            إذا (ق == [ ] أو (ق[-١] != '(' وح == ')') أو (ق[-١] != '[' وح == ']') أو (ق[-١] != '{' وح == '}')) {
                ارجع خطأ
            } وإلا {
                انزع(ق)
            }
        }
    }
    إذا (ق == [ ]) {
        ارجع صحيح
    } وإلا {
        ارجع خطأ
    }
}
